self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(FILES)).then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith('shelfy-') && key !== CACHE && key !== LAZY_CACHE)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => caches.open(LAZY_CACHE))
      .then((cache) =>
        cache
          .keys()
          .then((requests) =>
            Promise.all(requests.filter((r) => !LAZY.has(r.url)).map((r) => cache.delete(r))),
          ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;
  if (request.mode === 'navigate') {
    // The application page is cached as the scope URL, './' in FILES.
    event.respondWith(
      fetch(request).catch(() => caches.match(self.registration.scope, { ignoreVary: true })),
    );
    return;
  }
  if (LAZY.has(request.url)) {
    event.respondWith(
      caches.open(LAZY_CACHE).then((cache) =>
        cache.match(request, { ignoreVary: true }).then(
          (hit) =>
            hit ||
            fetch(request).then((response) => {
              if (response.ok) cache.put(request, response.clone());
              return response;
            }),
        ),
      ),
    );
    return;
  }
  // Module scripts and styles are requested with an Origin header that the precache requests
  // did not have; a Vary header of the server must not make them miss.
  event.respondWith(
    caches.match(request, { ignoreVary: true }).then((hit) => hit || fetch(request)),
  );
});
